script:
let $root = $(root_element);
let $body = $root.find('.hr-dashboard-body');
let $search = $root.find('.hr-search-input');
let curTab = 'leave';
let leaveData = [];
let tsData = [];

function fetchAll() {
    $body.html('<div style="text-align:center;padding:48px;color:#6b7280;"><div style="border:3px solid #e5e7eb;border-top-color:#2563eb;border-radius:50%;width:28px;height:28px;animation:hrspin .7s linear infinite;margin:0 auto 10px;"></div>Refreshing...</div>');
    frappe.call({
        method: 'enviro.api.hr.get_leave_applications',
        callback: r => {
            leaveData = r.message || [];
            $root.find('.hr-cnt-leave').text(leaveData.length);
            frappe.call({
                method: 'enviro.api.hr.get_timesheets',
                callback: r2 => {
                    tsData = r2.message || [];
                    $root.find('.hr-cnt-ts').text(tsData.length);
                    render();
                }
            });
        }
    });
}

function render() {
    let data = curTab === 'leave' ? leaveData : tsData;
    let q = $search.val().toLowerCase();
    if (q) {
        data = data.filter(d => (d.employee_name || '').toLowerCase().includes(q));
    }

    if (data.length === 0) {
        $body.html('<div style="text-align:center;padding:48px;color:#9ca3af;">No records found.</div>');
        return;
    }

    let h = '<div style="overflow-x:auto;"><table><thead><tr>';
    if (curTab === 'leave') {
        h += '<th>Employee</th><th>Leave From</th><th>Leave To</th><th>Leave Type</th><th>Status</th><th>Attachments</th><th>Action</th>';
    } else {
        h += '<th>Employee</th><th>Last Updated</th><th>TimeSheet Week</th><th>View</th><th>Access Log</th><th>Status</th>';
    }
    h += '</tr></thead><tbody>';

    data.forEach(d => {
        let isInactive = ['Approved', 'Rejected', 'Cancelled'].includes(d.status);
        let rowClass = isInactive ? 'hr-row-inactive' : '';
        let ini = (d.employee_name || '?').split(' ').map(w => w[0]||'').slice(0, 2).join('').toUpperCase();
        let photo = d.photo ? `<div class="hav"><img src="${d.photo}" onerror="this.outerHTML='<span>${ini}</span>'"></div>` : `<div class="hav">${ini}</div>`;

        h += `<tr class="${rowClass}">`;
        if (curTab === 'leave') {
            let att = d.attachments?.length ? d.attachments.map((u, i) => `<a href="${u}" target="_blank" style="color:#2563eb;font-size:12px;">📎 File ${i+1}</a>`).join('<br>') : '<span style="color:#9ca3af;font-size:12px;">No Attachment</span>';

            let actionBtn = '';
            if (d.status === 'Approved') {
                actionBtn = '<button class="lpill lpill-disabled" disabled>✓ Approved</button>';
            } else if (d.status === 'Cancelled') {
                actionBtn = '<button class="lpill lpill-disabled" disabled>Cancelled</button>';
            } else {
                actionBtn = `<button class="lpill lpill-g btn-leave-action" data-action="approve" data-name="${d.name}">Approve</button>
                             <button class="lpill lpill-r btn-leave-action" data-action="delete" data-name="${d.name}" style="margin-top:3px;">Cancel Request</button>`;
                if (d.status !== 'Rejected') {
                    actionBtn += `<button class="lpill lpill-r btn-leave-action" data-action="reject" data-name="${d.name}" style="margin-top:3px;background:#dc2626;">Reject</button>`;
                }
            }

            h += `<td><div style="display:flex;align-items:center;gap:8px;">${photo}<strong style="color:#111827;">${d.employee_name}</strong></div></td>
                  <td>${d.from_date}</td><td>${d.to_date}</td>
                  <td>📄 ${d.leave_type}</td>
                  <td><span class="hbdg ${getStatusClass(d.status)}">${d.status}</span></td>
                  <td>${att}</td>
                  <td style="min-width:110px;">${actionBtn}</td>`;
        } else {
            const week = d.week_beginning + (d.week_end ? ' - ' + d.week_end : '');
            let statusBtn = '';
            if (d.status === 'Approved') {
                statusBtn = '<span class="hbdg b-app" style="display:block;text-align:center;padding:6px 0;">✓ Approved</span>';
            } else if (d.status === 'Cancelled') {
                statusBtn = '<span class="hbdg b-can" style="display:block;text-align:center;padding:6px 0;">Cancelled</span>';
            } else if (d.status === 'Rejected') {
                statusBtn = '<span class="hbdg b-rej" style="display:block;text-align:center;padding:6px 0;">Rejected</span><button class="tbtn-app btn-ts-action" data-action="approve" data-name="' + d.name + '" style="margin-top:4px;">Approve</button>';
            } else {
                statusBtn = `<button class="tbtn-app btn-ts-action" data-action="approve" data-name="${d.name}">Approve</button>
                             <button class="lpill lpill-r btn-ts-action" data-action="delete" data-name="${d.name}" style="margin-top:4px;padding:4px 0;font-size:11px;">Cancel Request</button>`;
            }
            h += `<td><strong style="color:#111827;">${d.employee_name}</strong></td>
                  <td style="color:#6b7280;">${d.last_updated}</td><td style="white-space:nowrap;">${week}</td>
                  <td><button class="tbtn tbtn-v btn-ts-view" data-name="${d.name}">View</button></td>
                  <td><button class="tbtn tbtn-v btn-ts-log" data-emp="${d.employee}">View</button></td>
                  <td style="min-width:120px;">${statusBtn}</td>`;
        }
        h += '</tr>';
    });
    h += '</tbody></table></div>';
    $body.html(h);

    // Attach actions
    $body.find('.btn-leave-action').on('click', function() {
        let action = $(this).data('action');
        let name = $(this).data('name');
        let lbl = { approve: 'Approve', reject: 'Reject', delete: 'Cancel' }[action];
        frappe.confirm(`${lbl} this request?`, () => {
            frappe.call({
                method: `enviro.api.hr.${action}_leave`,
                args: { name: name },
                callback: () => { frappe.show_alert('Success'); fetchAll(); }
            });
        });
    });

    $body.find('.btn-ts-action').on('click', function() {
        let action = $(this).data('action');
        let name = $(this).data('name');
        let lbl = { approve: 'Approve', delete: 'Cancel' }[action] || action;
        frappe.confirm(`${lbl} this timesheet?`, () => {
            frappe.call({
                method: `enviro.api.hr.${action}_timesheet`,
                args: { name: name },
                callback: () => { frappe.show_alert('Success'); fetchAll(); }
            });
        });
    });

    $body.find('.btn-ts-view').on('click', function() {
        frappe.set_route('Form', 'Enviro Weekly Timesheet', $(this).data('name'));
    });

    $body.find('.btn-ts-log').on('click', function() {
        frappe.set_route('List', 'Enviro Weekly Timesheet', { employee: $(this).data('emp') });
    });
}

function getStatusClass(s) {
    let m = { Approved: 'b-app', Rejected: 'b-rej', Pending: 'b-pen', Open: 'b-ope', Draft: 'b-dra', Cancelled: 'b-can' };
    return m[s] || 'b-dra';
}

$root.find('.hr-tab-btn').on('click', function() {
    curTab = $(this).data('tab');
    $root.find('.hr-tab-btn').removeClass('btn-primary').addClass('btn-default');
    $root.find('.hr-tab-btn').css('border', '1.5px solid #d1d5db');
    $(this).addClass('btn-primary').removeClass('btn-default');
    $(this).css('border', 'none');
    render();
});

$search.on('input', render);
// Prevent awesome bar from hijacking search
$search.on('keydown keyup keypress focus click', e => e.stopPropagation());

fetchAll();

