e-between; align-items:center; background:#f8fafc; padding:15px; border-radius:12px;"><span style="color:#64748b; font-weight:600;">Active Faults</span><span id="ehb-s-af" style="font-size:18px; font-weight:800; color:#f97316;">0</span></div></div></div><div class="ehb-card"><div class="ehb-card-head"><span class="ehb-card-ttl">List of all Jobs</span><span class="ehb-see-all" onclick="frappe.set_route(\'List\',\'Enviro Job\')">See All</span></div><div class="ehb-card-body scrollable"><table class="ehb-tbl"><thead><tr><th>Code</th><th>Customer</th><th>Status</th></tr></thead><tbody id="ehb-jobs-rows"><tr><td colspan="3" class="ehb-empty">Loading…</td></tr></tbody></table></div></div><div class="ehb-card"><div class="ehb-card-head"><span class="ehb-card-ttl">Schedule</span></div><div class="ehb-card-body scrollable"><div class="ehb-sched-grid" id="ehb-sched-rows"></div></div></div><div class="ehb-card"><div class="ehb-card-head wx-card-head"><span class="ehb-card-ttl">Weather</span></div><div class="wx-card-body"><div class="wx-forecast-row" id="wx-forecast"></div><div class="wx-detail-row"><div class="wx-det-left" id="wx-desc">Loading…</div><div class="wx-det-mid" id="wx-temp">--°C</div><div class="wx-det-right" id="wx-clock-stack"></div></div></div></div></div></div>';
function ehbTick() {const n = new Date();const stack = root_element.querySelector("#wx-clock-stack");if(stack) {const time = n.toLocaleTimeString([], {timeZone: "Australia/Sydney", hour:"2-digit", minute:"2-digit", second:"2-digit", hour12:true});const day = n.toLocaleDateString(undefined, {timeZone: "Australia/Sydney", weekday:"long"});const date = n.toLocaleDateString(undefined, {timeZone: "Australia/Sydney", day:"numeric", month:"short", year:"numeric"}).replace(/ /g, "-");stack.innerHTML = '<div class="wx-blue">'+time+'</div><div>'+day+'</div><div class="wx-blue">'+date+'</div>';}const dtEl = root_element.querySelector("#ehb-date");if(dtEl) dtEl.innerText = n.toLocaleDateString(undefined, {weekday:"long", day:"numeric", month:"long", year:"numeric"});}
