            this.classList.add('active');

            const selectedCat = this.getAttribute('data-cat');
            const searchTerm = (root_element.querySelector('#veh-search').value || '').toLowerCase();

            root_element.querySelectorAll('.env-veh-row').forEach(row => {
                const rowCat = row.getAttribute('data-category');
                const rowText = row.innerText.toLowerCase();

                let matchesCat = (selectedCat === 'All' || selectedCat === rowCat);
                let matchesSearch = rowText.includes(searchTerm);

                if(matchesCat && matchesSearch) {
                    row.style.display = 'table-row';
                } else {
                    row.style.display = 'none';
                }
            });
        });
    });

    root_element.querySelectorAll('.env-veh-row').forEach(row => {
