            frappe.set_route('Form', 'Vehicle', this.getAttribute('data-name'));
        });
    });

    // Real-time Search Logic
    const searchInput = root_element.querySelector('#veh-search');
    if (searchInput) {
        searchInput.addEventListener('keydown', e => e.stopPropagation());
        searchInput.addEventListener('input', e => {
            e.stopPropagation();
            const searchTerm = e.target.value.toLowerCase();

            // Look through every row
            root_element.querySelectorAll('.env-veh-row').forEach(row => {
                // Get all the text content inside that specific row
                const rowText = row.innerText.toLowerCase();

                // Show row if it matches, hide if it doesn't
                const activeCat = root_element.querySelector('.v-cat-pill.active').getAttribute('data-cat');
                const rowCat = row.getAttribute('data-category');
                let matchesCat = (activeCat === 'All' || activeCat === rowCat);
                if (rowText.includes(searchTerm) && matchesCat) {
                    row.style.display = 'table-row';
                } else {
                    row.style.display = 'none';
                }
            });
        });
    }
});

