        const btnCurrent = root_element.querySelector('#btn-show-current');
        const btnTerminated = root_element.querySelector('#btn-show-terminated');
        const sectionTitle = root_element.querySelector('#env-emp-section-title');

        btnCurrent.addEventListener('click', () => {
            btnCurrent.classList.add('active');
            btnTerminated.classList.remove('active');
            sectionTitle.innerText = "Current Employees";
            drawEmployees('Active');
        });

        btnTerminated.addEventListener('click', () => {
            btnTerminated.classList.add('active');
            btnCurrent.classList.remove('active');
            sectionTitle.innerText = "Terminated Employees";
            drawEmployees('Left');
        });

        const searchInput = root_element.querySelector('#env-local-search');
        if (searchInput) {
            searchInput.addEventListener('keydown', e => e.stopPropagation());
            searchInput.addEventListener('input', e => {
                e.stopPropagation();
                const searchTerm = e.target.value.toLowerCase();
                root_element.querySelectorAll('.env-card').forEach(card => {
                    const empName = card.querySelector('.env-name').innerText.toLowerCase();
                    card.style.display = empName.includes(searchTerm) ? 'block' : 'none';
                });
            });
        }

        root_element.querySelector('#env-add-folder-btn').addEventListener('click', () => {
            frappe.prompt([{ label: 'Folder Name', fieldname: 'folder_name', fieldtype: 'Data', reqd: 1 }], (values) => {
                frappe.call({
                    method: 'frappe.client.insert',
                    args: { doc: { doctype: 'Enviro Team Folder', folder_name: values.folder_name } },
                    callback: (r) => { if(!r.exc) drawTeamFolders(); }
                });
            }, 'New Folder', 'Create');
        });
    }

    function drawEmployees(status_filter = 'Active') {
        const container = root_element.querySelector('#env-employee-container');
        container.innerHTML = '<div style="text-align: center; padding: 40px; color: #9ca3af;">Loading Employees...</div>';

        let filters = { status: 'Active' };
        if (status_filter === 'Left') {
            filters = { status: ['in', ['Left', 'Inactive']] };
        }

        frappe.db.get_list('Employee', {
            fields: ['name', 'employee_name', 'image'],
            filters: filters,
            limit: 100,
            order_by: 'employee_name asc'
        }).then(employees => {
            if (!employees || employees.length === 0) {
                container.innerHTML = `<div style="text-align: center; padding: 40px; color: #9ca3af; font-style: italic;">No employees found in this section.</div>`;
                return;
            }

            let html = '<div class="env-grid">';
            employees.forEach(emp => {
                let img_html = emp.image ? `<img src="${emp.image}" class="env-avatar">` : '<div class="env-avatar">👤</div>';
                html += `
                    <div class="env-card" data-emp="${emp.name}">
                        ${img_html}
                        <div class="env-name">${emp.employee_name}</div>
                    </div>
                `;
            });
            html += '</div>';
            container.innerHTML = html;

            container.querySelectorAll('.env-card').forEach(card => {
                card.addEventListener('click', function() { renderEmployeeProfile(this.getAttribute('data-emp')); });
            });
        });
    }

    const globalEnvFolders = {
        "Employee Contracts": ["contract", "agreement", "offer"],
        "Medical & Health": ["doctor", "medical", "certificate", "health"],
        "Leave Applications": ["leave", "annual", "holiday"],
        "Compliance & Policies": ["police", "check", "conduct", "policy", "induction"],
        "Other Documents": [] 
    };

    function getEmployeeFilesForFolder(folderName, empFiles) {
        if (folderName === "Other Documents") {
            return empFiles.filter(f => {
                let name = (f.file_name || "").toLowerCase();
                let matchesOther = Object.entries(globalEnvFolders).some(([key, keywords]) => {
                    if(key === "Other Documents") return false;
                    return keywords.some(kw => name.includes(kw));
                });
                return !matchesOther;
            });
        }
        let keywords = globalEnvFolders[folderName];
        if (!keywords) return []; 
        return empFiles.filter(f => {
            let name = (f.file_name || "").toLowerCase();
            return keywords.some(kw => name.includes(kw));
        });
    }

    function drawTeamFolders() {
        const container = root_element.querySelector('#env-folder-container');

        Promise.all([
            frappe.db.get_list('Enviro Team Folder', { fields: ['name'], limit: 1000 }),
            frappe.db.get_list('File', { filters: { attached_to_doctype: 'Enviro Team Folder' }, fields: ['attached_to_name'], limit: 10000 }),
            frappe.db.get_list('File', { filters: { attached_to_doctype: 'Employee' }, fields: ['file_name'], limit: 10000 })
        ]).then(([folders, teamFiles, empFiles]) => {
            let html = '<div class="env-folder-grid">';
            (folders || []).forEach(f => {
                let teamCount = (teamFiles || []).filter(file => file.attached_to_name === f.name).length;
                let empCount = getEmployeeFilesForFolder(f.name, empFiles || []).length;
                let count = teamCount + empCount;
                html += `
                    <div class="env-folder" data-folder="${f.name}">
                        <div style="font-size: 24px; color: #fbbf24;">📁</div>
                        <div>
                            <div style="font-weight: bold;">${f.name}</div>
                            <div style="font-size: 11px; color: #9ca3af;">${count} files</div>
                        </div>
                    </div>
                `;
            });
            html += '</div>';
            container.innerHTML = html;

            container.querySelectorAll('.env-folder').forEach(el => {
                el.addEventListener('click', function() { drawTeamFiles(this.getAttribute('data-folder')); });
            });
        });
    }

    function drawTeamFiles(folderName) {
        const container = root_element.querySelector('#env-folder-container');
        container.innerHTML = '<div style="text-align: center; padding: 40px; color: #9ca3af;">Loading Files...</div>';

        Promise.all([
            frappe.db.get_list('File', { filters: { attached_to_doctype: 'Enviro Team Folder', attached_to_name: folderName }, fields: ['name', 'file_name', 'file_url', 'attached_to_name'], limit: 10000 }),
            frappe.db.get_list('File', { filters: { attached_to_doctype: 'Employee' }, fields: ['name', 'file_name', 'file_url', 'attached_to_name'], limit: 10000 })
        ]).then(([teamFiles, allEmpFiles]) => {
            let empFiles = getEmployeeFilesForFolder(folderName, allEmpFiles || []);
            let files = [...(teamFiles || []), ...empFiles];

            let html = `
                <div style="display: flex; align-items: center; gap: 10px; margin-bottom: 15px;">
                    <button class="env-action-btn" id="env-back-btn">⬅ Back to Folders</button>
                    <h3 style="margin: 0; color: #374151; font-size:16px;">📁 ${folderName}</h3>
                    <button class="env-action-btn primary" id="btn-upload-team-file" style="margin-left: auto;">+ Upload Document</button>
                </div>
                <div class="env-folder-grid">
            `;

            if (!files || files.length === 0) {
                html += '<div style="grid-column: 1 / -1; padding: 20px; color: #9ca3af; font-style: italic; text-align:center;">No documents in this folder yet.</div>';
            } else {
                files.forEach(f => {
                    let subtitleText = (f.attached_to_name && f.attached_to_name !== folderName) ? ` (Emp: ${f.attached_to_name})` : '';
                    let subtitleHtml = subtitleText ? `<div style="font-size: 10px; color: #9ca3af; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100px;">${subtitleText}</div>` : '';
                    html += `
                        <div class="env-file" title="${f.file_name}" data-url="${f.file_url}" style="display:flex; flex-direction:column; align-items:flex-start; gap:2px;">
                            <div style="white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%;">📄 ${f.file_name}</div>
                            ${subtitleHtml}
                        </div>`;
                });
            }

            html += '</div>';
            container.innerHTML = html;

            root_element.querySelector('#env-back-btn').addEventListener('click', drawTeamFolders);

            root_element.querySelector('#btn-upload-team-file').addEventListener('click', () => {
                new frappe.ui.FileUploader({
                    doctype: 'Enviro Team Folder',
                    docname: folderName,
                    on_success: (file_doc) => {
                        frappe.show_alert({message: 'File uploaded successfully!', indicator: 'green'});
                        drawTeamFiles(folderName);
                    }
                });
            });

            container.querySelectorAll('.env-file').forEach(el => {
                el.addEventListener('click', function() { window.open(this.getAttribute('data-url'), '_blank'); });
            });
        });
    }

    function renderEmployeeProfile(override_employee_id = null) {
        let get_emp_promise = override_employee_id ? 
            Promise.resolve({message: {name: override_employee_id}}) : 
            frappe.db.get_value('Employee', {'user_id': frappe.session.user}, 'name');

        get_emp_promise.then(r => {
            if(r && r.message) {
                let employee_id = r.message.name;
                Promise.all([
                    frappe.db.get_doc('Employee', employee_id),
                    frappe.db.get_list('File', { filters: { attached_to_doctype: 'Employee', attached_to_name: employee_id }, fields: ['file_name', 'file_url'], limit: 1000 }),
                    frappe.db.get_value('User', frappe.session.user, 'mobile_no')
                ]).then(([doc, files, user_res]) => {
                    let user_mobile = user_res && user_res.message ? user_res.message.mobile_no : null;
                    let envUserFiles = files || [];
                    let img_html = doc.image ? `<img src="${doc.image}" class="env-profile-pic">` : '<div class="env-profile-pic">👤</div>';
                    let formatDate = (dateString) => dateString ? frappe.datetime.str_to_user(dateString) : 'N/A';
                    const envFolders = {
                        "Employee Contracts": ["contract", "agreement", "offer"],
                        "Medical & Health": ["doctor", "medical", "certificate", "health"],
                        "Leave Applications": ["leave", "annual", "holiday"],
                        "Compliance & Policies": ["police", "check", "conduct", "policy", "induction"],
                        "Other Documents": [] 
                    };
                    function getFilesInFolder(folderName) {
                        if (folderName === "Other Documents") {
                            return envUserFiles.filter(f => {
                                let name = f.file_name.toLowerCase();
                                let matchesOther = Object.entries(envFolders).some(([key, keywords]) => {
                                    if(key === "Other Documents") return false;
                                    return keywords.some(kw => name.includes(kw));
                                });
                                return !matchesOther;
                            });
                        }
                        let keywords = envFolders[folderName];
                        return envUserFiles.filter(f => { let name = f.file_name.toLowerCase(); return keywords.some(kw => name.includes(kw)); });
                    }
                    function triggerUpload(currentView, folderName = null) {
                        new frappe.ui.FileUploader({
                            doctype: 'Employee', docname: employee_id,
                            on_success: (file_doc) => {
                                let promise = Promise.resolve();
                                if (folderName && folderName !== "Other Documents" && envFolders[folderName].length > 0) {
                                    let kw = envFolders[folderName][0];
                                    if (!file_doc.file_name.toLowerCase().includes(kw)) {
                                        let new_name = kw + "_" + file_doc.file_name;
                                        promise = frappe.call({
                                            method: 'frappe.client.set_value',
                                            args: { doctype: 'File', name: file_doc.name, fieldname: 'file_name', value: new_name }
                                        });
                                    }
                                }
                                promise.then(() => {
                                    frappe.db.get_list('File', { filters: { attached_to_doctype: 'Employee', attached_to_name: employee_id }, fields: ['file_name', 'file_url'], limit: 1000 })
                                    .then(updated_files => {
                                        envUserFiles = updated_files || [];
                                        if(currentView === 'files') { drawFiles(folderName); } else { drawFolders(); }
                                        frappe.show_alert({message: 'File uploaded successfully!', indicator: 'green'});
                                    });
                                });
                            }
                        });
                    }

                    let back_btn_html = override_employee_id ? `<button class="env-action-btn" id="btn-back-to-team" style="background:white; color:#0f172a; margin-right:auto;">⬅ Back to Team</button>` : '';
                    let profileHtml = styles + `
                        <div class="emp-prof-wrapper">
                            <div class="env-banner">
                                ${back_btn_html}
                                <div style="display: flex; gap: 10px; align-items: flex-start; margin-left:auto;">
                                    <button class="env-action-btn" id="btn-timesheet">📅 Timesheet</button>
                                    <button class="env-action-btn" id="btn-leave">🏖️ Leave Application</button>
                                </div>
                            </div>
                            <div class="env-profile-container">
                                <div class="env-left-col">
                                    ${img_html}
                                    <div class="env-name-title">${doc.employee_name}</div>
                                    <div class="env-detail-row"><div class="env-detail-label">Joined Date</div><div class="env-detail-value">${formatDate(doc.date_of_joining)}</div></div>
                                    <div class="env-detail-row"><div class="env-detail-label">Position Title</div><div class="env-detail-value">${doc.custom_position_title || doc.designation || doc.employment_type || 'N/A'}</div></div>
                                    <div class="env-detail-row"><div class="env-detail-label">Contact No</div><div class="env-detail-value">${doc.cell_number || user_mobile || doc.personal_email || 'N/A'}</div></div>
                                    <div class="env-detail-row"><div class="env-detail-label">Email</div><div class="env-detail-value">${doc.company_email || 'N/A'}</div></div>
                                    <div class="env-detail-row"><div class="env-detail-label">Employment Status</div><div class="env-detail-value">${doc.status}</div></div>
                                    <div class="env-detail-row"><div class="env-detail-label">DOB</div><div class="env-detail-value">${formatDate(doc.date_of_birth)}</div></div>
                                    <button class="env-update-btn" id="btn-update-info">Update Info</button>
                                </div>
                                <div class="env-right-col">
                                    <div id="env-folder-header" style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 20px;"></div>
                                    <div id="env-folder-grid" class="env-folder-grid"></div>
                                </div>
                            </div>
                        </div>
                    `;
                    root_element.innerHTML = profileHtml;
                    if (override_employee_id) {
                        root_element.querySelector('#btn-back-to-team').addEventListener('click', () => renderManagerDashboard());
                    }
                    root_element.querySelector('#btn-timesheet').addEventListener('click', () => frappe.new_doc('Enviro Weekly Timesheet', { employee: doc.name }));
                    root_element.querySelector('#btn-leave').addEventListener('click', () => frappe.set_route('List', 'Leave Application'));
                    root_element.querySelector('#btn-update-info').addEventListener('click', () => frappe.set_route('Form', 'Employee', doc.name));

                    function drawFolders() {
                        let header = root_element.querySelector('#env-folder-header');
                        let grid = root_element.querySelector('#env-folder-grid');
                        header.innerHTML = '<h3 style="margin: 0; color: #374151;">Folders</h3><button class="env-action-btn primary" id="btn-upload-folder">+ Upload Document</button>';
                        let gridHtml = '';
                        Object.keys(envFolders).forEach(folderName => {
                            let count = getFilesInFolder(folderName).length;
                            let emoji = folderName === "Other Documents" ? "📂" : "📁";
                            gridHtml += `<div class="env-folder" data-folder="${folderName}"><div style="font-size: 24px; color: #fbbf24;">${emoji}</div><div><div style="font-weight: bold;">${folderName}</div><div style="font-size: 11px; color: #9ca3af;">${count} files</div></div></div>`;
                        });
                        grid.innerHTML = gridHtml;
                        header.querySelector('#btn-upload-folder').addEventListener('click', () => triggerUpload('folders'));
                        grid.querySelectorAll('.env-folder').forEach(el => { el.addEventListener('click', function() { drawFiles(this.getAttribute('data-folder')); }); });
                    }

                    function drawFiles(folderName) {
                        let header = root_element.querySelector('#env-folder-header');
                        let grid = root_element.querySelector('#env-folder-grid');
                        header.innerHTML = `<div style="display: flex; align-items: center; gap: 10px;"><button class="env-action-btn" id="env-back-btn">⬅ Back</button><h3 style="margin: 0; color: #374151;">📁 ${folderName}</h3></div><button class="env-action-btn primary" id="btn-upload-file">+ Upload Document</button>`;
                        let files_to_show = getFilesInFolder(folderName);
                        let gridHtml = '';
                        if (files_to_show.length === 0) { gridHtml = '<div style="grid-column: 1 / -1; padding: 20px; color: #9ca3af; font-style: italic;">No documents in this folder yet.</div>'; } 
                        else { files_to_show.forEach(f => { gridHtml += `<div class="env-file" title="${f.file_name}" data-url="${f.file_url}">📄 ${f.file_name}</div>`; }); }
                        grid.innerHTML = gridHtml;
                        header.querySelector('#env-back-btn').addEventListener('click', drawFolders);
                        header.querySelector('#btn-upload-file').addEventListener('click', () => triggerUpload('files', folderName));
                        grid.querySelectorAll('.env-file').forEach(el => { el.addEventListener('click', function() { window.open(this.getAttribute('data-url'), '_blank'); }); });
                    }
                    drawFolders();
                });
            } else {
                 root_element.innerHTML = styles + '<div class="env-wrapper" style="color: #dc2626; text-align: center; padding: 40px;"><b>Error:</b> No Employee profile is linked to your current user account.</div>';
            }
        });
    }

    if (is_manager) {
        renderManagerDashboard();
    } else {
        renderEmployeeProfile();
    }
})();

