frappe.db.get_list('Industry Type', { fields: ['name'], limit: 0, order_by: 'name asc' }).then(industries => {
    let industry_options = industries.map(i => `<option value="${i.name}">${i.name}</option>`).join('');

    let layout = `
        <div class="env-wrapper">
