            </div>

            <div class="env-grid" id="env-site-grid">
                <div style="grid-column: 1 / -1; text-align: center; padding: 40px; color: #64748b;">Loading Sites...</div>
            </div>
        </div>
    `;

    root_element.innerHTML = styles + layout;

    root_element.querySelector('#add-site-btn').addEventListener('click', () => frappe.new_doc('Site'));

    const searchInput = root_element.querySelector('#site-search');
    const industryFilter = root_element.querySelector('#industry-filter');
    const filterBtns = root_element.querySelectorAll('.env-filter-btn');

    function fetch_and_render_sites() {
        const searchTerm = searchInput.value;
        const activeFilter = root_element.querySelector('.env-filter-btn.active').getAttribute('data-filter');
        const selectedIndustry = industryFilter.value;

        let db_filters = {};
        if (searchTerm) {
            db_filters['name'] = ['like', '%' + searchTerm + '%'];
        }
        if (selectedIndustry !== 'All') {
            db_filters['industry_type'] = selectedIndustry;
        }
        if (activeFilter === 'Permanent') {
            db_filters['site_type'] = 'Permanent Site';
            db_filters['disabled'] = 0;
        } else if (activeFilter === 'Temporary') {
            db_filters['site_type'] = 'Temporary Site';
            db_filters['disabled'] = 0;
        } else if (activeFilter === 'Deleted') {
            db_filters['disabled'] = 1;
        }

        root_element.querySelector('#env-site-grid').innerHTML = `<div style="grid-column: 1 / -1; text-align: center; padding: 40px; color: #64748b;">Loading...</div>`;

        frappe.db.get_list('Site', {
            fields: ['name', 'site_type', 'disabled', 'industry_type', 'site_address', 'custom_site_image'], 
            filters: db_filters,
            limit: 60,
            order_by: 'creation desc'
        }).then(sites => {
            let grid_html = '';
            if (sites.length === 0) {
                grid_html = `<div style="grid-column: 1 / -1; text-align: center; padding: 40px; color: #64748b;">No sites found for these filters.</div>`;
            } else {
                sites.forEach(site => {
                    let badge_class = 'badge-unknown';
                    let display_status = 'Unknown';

                    if (site.disabled === 1) {
                        badge_class = 'badge-deleted';
                        display_status = 'Deleted';
                    } else if (site.site_type === 'Permanent Site') {
                        badge_class = 'badge-permanent';
                        display_status = 'Permanent';
                    } else if (site.site_type === 'Temporary Site') {
                        badge_class = 'badge-temporary';
                        display_status = 'Temporary';
                    }

                    let site_icon_html = site.custom_site_image ? `<img src="${site.custom_site_image}" style="width: 100%; height: 100%; object-fit: cover; border-radius: 12px;">` : `🏢`;

                    grid_html += `
