    // --- Events & Interactivity ---
    function bind_events_main() {
        // Tab Clicks
        root_element.querySelectorAll('.tab-btn[data-tab]').forEach(btn => {
            btn.addEventListener('click', function() {
                state.activeTab = this.getAttribute('data-tab');
                render();
            });
        });

        let mFilter = root_element.querySelector('#perf-month');
        if (mFilter) mFilter.addEventListener('change', function() { state.selectedMonth = this.value; render(); });

        let yFilter = root_element.querySelector('#perf-year');
        if (yFilter) yFilter.addEventListener('change', function() { state.selectedYear = this.value; render(); });

        let generateBtn = root_element.querySelector('#btn-generate');
        if(generateBtn) generateBtn.addEventListener('click', () => frappe.new_doc('Quotation'));

        let exportBtn = root_element.querySelector('#btn-export-sales');
        if (exportBtn) {
            exportBtn.addEventListener('click', () => {
                if (!state.quotes || state.quotes.length === 0) {
                    frappe.show_alert({message: 'No data to export', indicator: 'orange'});
                    return;
                }

                let data_to_export = [];
                if (state.activeTab === 'Quote Register') {
                    data_to_export = state.quotes.filter(q => q.docstatus === 0);
                } else {
                    data_to_export = state.quotes.filter(q => q.docstatus === 1 || q.docstatus === 2);
                }

                let csvContent = "data:text/csv;charset=utf-8,";
                let headers = state.activeTab === 'Quote Register' ? 
                    ["Quote No", "Date", "Customer", "Mobile", "Sales Person", "Status"] :
                    ["Job Code", "Quote No", "Date", "Customer", "Quoted by", "Amount", "Status"];

                csvContent += headers.join(",") + "\r\n";

                data_to_export.forEach(q => {
                    let row = [];
                    if (state.activeTab === 'Quote Register') {
                        row = [
                            q.name,
                            q.transaction_date,
                            '"' + (q.customer_name || "").replace(/"/g, '""') + '"',
                            q.contact_mobile || "",
                            (q.owner || "").split('@')[0],
                            q.status
                        ];
                    } else {
                        row = [
                            q.custom_enviro_job_card || "None",
                            q.name,
                            q.transaction_date,
                            '"' + (q.customer_name || "").replace(/"/g, '""') + '"',
                            (q.owner || "").split('@')[0],
                            q.grand_total,
                            q.status
                        ];
                    }
                    csvContent += row.join(",") + "\r\n";
                });

                const encodedUri = encodeURI(csvContent);
                const link = document.createElement("a");
                link.setAttribute("href", encodedUri);
                link.setAttribute("download", `sales_${state.activeTab.toLowerCase().replace(" ", "_")}_report.csv`);
                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);
            });
        }

        root_element.querySelectorAll('.action-btn.view').forEach(btn => {
            btn.addEventListener('click', function() {
                frappe.set_route('Form', 'Quotation', this.getAttribute('data-name'));
            });
        });

        root_element.querySelectorAll('.action-btn.delete').forEach(btn => {
            btn.addEventListener('click', function() {
                let name = this.getAttribute('data-name');
                frappe.confirm(`Are you sure you want to delete ${name}?`, () => {
                    frappe.client.delete('Quotation', name).then(() => fetch_data());
                });
            });
        });

        root_element.querySelectorAll('.action-btn.resend').forEach(btn => {
            btn.addEventListener('click', function() {
                let name = this.getAttribute('data-name');
                frappe.db.get_value('Quotation', name, ['custom_site_email', 'custom_enviro_job_card']).then(r => {
                    if(!r.message.custom_site_email) {
                        frappe.msgprint({title: 'Error', message: 'No Site Email linked to this Quotation.', indicator:'red'});
                        return;
                    }
                    if(!r.message.custom_enviro_job_card) {
                        frappe.msgprint({title: 'Error', message: 'You must link an Enviro Job Card first.', indicator:'red'});
                        return;
                    }

                    let d = new frappe.ui.Dialog({
                        title: 'Preview Client Quotation',
                        fields: [
                            {
                                fieldname: 'preview_html',
                                fieldtype: 'HTML',
                                options: `<div style="width: 100%; height: 80vh; overflow: hidden; border: 1px solid #d1d5db; border-radius: 8px;">
                                    <iframe src="/quote_view?name=${name}&preview=1" style="width: 100%; height: 100%; border: none;"></iframe>
                                </div>`
                            }
                        ],
                        size: 'extra-large',
                        primary_action_label: 'Approve & Continue to Send',
                        primary_action: function() {
                            d.hide();
                            frappe.prompt([
                                { label: 'CC', fieldname: 'cc', fieldtype: 'Data', description: 'Comma separated email addresses' },
                                { label: 'BCC', fieldname: 'bcc', fieldtype: 'Data', description: 'Comma separated email addresses' },
                                { label: 'Mail Body (Optional)', fieldname: 'custom_message', fieldtype: 'Text', description: 'Add a custom message to the client' }
                            ], function(values){
                                frappe.call({
                                    method: 'enviro.custom_scripts.quotation.send_approval_email',
                                    args: { docname: name, cc: values.cc, bcc: values.bcc, custom_message: values.custom_message },
                                    freeze: true,
                                    freeze_message: "Dispatching Email securely...",
                                    callback: function(res) {
                                        if (!res.exc) {
                                            frappe.show_alert({message: "Approval email precisely dispatched to the site manager!", indicator: 'green'});
                                            fetch_data();
                                        }
                                    }
                                });
                            }, 'Email Options', 'Send Email');
                        }
                    });
                    d.show();
                });
            });
        });

        root_element.querySelectorAll('.action-btn.submit').forEach(btn => {
            btn.addEventListener('click', function() {
                let name = this.getAttribute('data-name');
                frappe.confirm(`Finalize and Submit Quotation ${name} to the Accounts Team?`, () => {
                    frappe.call({
                        method: 'enviro.custom_scripts.quotation.submit_quotation',
                        args: { name: name },
                        freeze: true,
                        freeze_message: "Submitting Quotation...",
                        callback: function(r) {
                            if (!r.exc) {
                                frappe.show_alert({message: "Sales Team Approved! Quotation Submitted.", indicator: 'green'});
                                fetch_data(); 
                            } else {
                                frappe.msgprint({title: "Submit Failed", message: "Check validation errors.", indicator: 'red'});
                            }
                        }
                    });
                });
            });
        });

        root_element.querySelectorAll('.action-btn.approve').forEach(btn => {
            btn.addEventListener('click', function() {
                let name = this.getAttribute('data-name');
                frappe.confirm(`Approve Quotation ${name} for Accounts/Dispatch?`, () => {
                   frappe.db.set_value('Quotation', name, 'custom_accounts_approval_status', 'Approved').then(() => {
                        frappe.show_alert({message: "Accounts Team Approved!", indicator: 'green'});
                        fetch_data();
                   });
                });
            });
        });

        root_element.querySelectorAll('.user-card').forEach(card => {
            card.addEventListener('click', function() {
                state.selectedUser = this.getAttribute('data-user');
                state.currentView = 'user_detail';
                render();
            });
        });
    }

    function bind_events_user_detail() {
        let backBtn = root_element.querySelector('#btn-back-dashboard');
        if (backBtn) {
            backBtn.addEventListener('click', () => {
                state.currentView = 'main';
                state.selectedUser = null;
                render();
            });
        }

        root_element.querySelectorAll('.view-detail').forEach(btn => {
            btn.addEventListener('click', function() {
                frappe.set_route('Form', 'Quotation', this.getAttribute('data-name'));
            });
        });

        let exportBtn = root_element.querySelector('#btn-export-user-report');
        if (exportBtn) {
            exportBtn.addEventListener('click', () => {
                // Similar export logic for user details
                const { filteredPerfQuotes } = get_user_stats(state.quotes, state.selectedUser);
                let targetQuotes = filteredPerfQuotes.filter(q => {
                    let displayName = (q.owner || 'Unknown').split('@')[0];
                    if(displayName.length > 15) displayName = displayName.substring(0, 15);
                    return displayName === state.selectedUser;
                });

                if (targetQuotes.length === 0) {
                    frappe.show_alert({message: 'No data to export', indicator: 'orange'});
                    return;
                }

                let csvContent = "data:text/csv;charset=utf-8,";
                csvContent += "Quote,Won / Reject Date,Client Id,Client Name,Client Email,Sales Team Review,Paid Status\r\n";

                targetQuotes.forEach(q => {
                    let statusText = q.status;
                    if (q.status === 'Ordered' || q.status === 'Submitted') statusText = 'Approved';
                    else if (q.status === 'Lost' || q.status === 'Cancelled' || q.status === 'Rejected') statusText = 'Rejected';
                    else statusText = 'Pending';
                    let actionDate = q.modified ? frappe.datetime.str_to_user(q.modified) : frappe.datetime.str_to_user(q.transaction_date);
                    if (statusText === 'Pending') actionDate = '-';

                    let row = [
                        q.name,
                        actionDate,
                        q.party_name || "",
                        '"' + (q.customer_name || "").replace(/"/g, '""') + '"',
                        q.custom_site_email || "",
                        statusText,
                        "un-paid"
                    ];
                    csvContent += row.join(",") + "\r\n";
                });

                const encodedUri = encodeURI(csvContent);
                const link = document.createElement("a");
                link.setAttribute("href", encodedUri);
                link.setAttribute("download", `sales_performance_${state.selectedUser}.csv`);
                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);
            });
        }
    }

    // --- Bootstrapper ---
    function fetch_data() {
        root_element.innerHTML = `<div style="padding: 40px; text-align:center;">Loading Live Workspace...</div>`;

        frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype: 'Quotation',
                fields: ['name', 'docstatus', 'status', 'transaction_date', 'customer_name', 'owner', 'party_name', 'custom_site_email',
                         'contact_mobile', 'grand_total', 'currency', 'modified',
                         'custom_client_approval_status', 'custom_accounts_approval_status', 'custom_enviro_job_card', 'custom_requires_client_approval'],
                limit_page_length: 500,
                order_by: 'creation desc'
            },
            callback: function(r) {
                if (r.message) {
                    state.quotes = r.message;
                }
                render();
            }
        });
    }

    // Start!
    fetch_data();

const styles = `
