let state = {
   queue_jobs: [], scheduled_jobs: [], vehicles: [], employees: [], dates: [], active_tab: 'One-Off',
   grid_mode: 'vehicles', // 'vehicles', 'members', or 'terminated'
   from_date: moment().startOf('week').add(1, 'days').format('YYYY-MM-DD'), // Monday
   to_date: moment().startOf('week').add(7, 'days').format('YYYY-MM-DD')    // Sunday
};

function update_matrix_dates() {
    state.dates = [];
    let start = moment(state.from_date);
    let end = moment(state.to_date);
    let curr = start.clone();
    let count = 0;
    while (curr.isSameOrBefore(end) && count < 62) {
        state.dates.push(curr.toDate());
        curr.add(1, 'days');
        count++;
    }
}

function render() {
   update_matrix_dates();
   let unscheduled_all = state.queue_jobs.filter(j => j.status !== 'Assigned');

   let count1 = unscheduled_all.filter(j => j.is_reoccurring_quote !== 'YES' && j.status !== 'Cancelled').length;
   let count2 = unscheduled_all.filter(j => j.is_reoccurring_quote === 'YES' && j.status !== 'Cancelled').length;
   let count3 = unscheduled_all.filter(j => j.is_outsourced_job === 'YES' && j.status !== 'Cancelled').length;
   let count4 = state.queue_jobs.filter(j => j.status === 'Cancelled').length;

   let html = styles + `
        <div class="filter-bar" style="display: flex; gap: 15px; background: transparent; border: none; padding: 0;">
