            <div style="flex: 0 0 550px;"></div>

            <!-- Right Side Filters (Aligns with Right Panel) -->
            <div style="flex: 1; background: #f9fafb; padding: 8px 10px; border-radius: 10px; border: 1px solid #e5e7eb; display: flex; justify-content: space-between; align-items: center; min-width: 0; gap: 5px;">

                <div class="mode-toggle">
                    <button class="toggle-btn ${state.grid_mode === 'vehicles' ? 'active' : ''}" data-mode="vehicles">Vehicles</button>
                    <button class="toggle-btn ${state.grid_mode === 'members' ? 'active' : ''}" data-mode="members">Members</button>
                    <button class="toggle-btn ${state.grid_mode === 'terminated' ? 'active' : ''}" data-mode="terminated">Terminated</button>
                </div>

                <div style="display: flex; gap: 5px; align-items: center;">
