                        <span>To:</span>
                        <input type="date" class="filter-input" id="filter-to" value="${state.to_date}">
                    </div>
                    <button class="btn-clear" id="btn-clear-filters">Clear</button>
                    <button id="btn-export-sched" style="background: #10b981; color: white; border: none; padding: 4px 12px; border-radius: 20px; font-weight: bold; font-size: 11px; cursor: pointer; white-space: nowrap;">Export Report</button>
                </div>
            </div>
        </div>

<div class="sched-wrapper">`;

   html += `<div class="sched-left">
        <div class="tabs-container">
            <div class="tab ${state.active_tab === 'One-Off' ? 'active' : ''}" onclick="window.set_tab('One-Off')">One-Off <span class="tab-count">${count1}</span></div>
            <div class="tab ${state.active_tab === 'Reoccurring' ? 'active' : ''}" onclick="window.set_tab('Reoccurring')">Reoccurring <span class="tab-count">${count2}</span></div>
            <div class="tab ${state.active_tab === 'Outsourced' ? 'active' : ''}" onclick="window.set_tab('Outsourced')">Outsourced <span class="tab-count">${count3}</span></div>
            <div class="tab ${state.active_tab === 'Deleted' ? 'active' : ''}" onclick="window.set_tab('Deleted')">Deleted <span class="tab-count">${count4}</span></div>
        </div>
        <div class="queue-table-wrapper">
            <table class="queue-table">
                <thead><tr><th>Job</th><th>Client</th><th>Waste Type</th><th>Status</th><th>Action</th></tr></thead>
                <tbody>
   `;

   let filtered = [];
   if(state.active_tab === 'One-Off') filtered = unscheduled_all.filter(j => j.is_reoccurring_quote !== 'YES' && j.status !== 'Cancelled');
   if(state.active_tab === 'Reoccurring') filtered = unscheduled_all.filter(j => j.is_reoccurring_quote === 'YES' && j.status !== 'Cancelled');
   if(state.active_tab === 'Outsourced') filtered = unscheduled_all.filter(j => j.is_outsourced_job === 'YES' && j.status !== 'Cancelled');
   if(state.active_tab === 'Deleted') filtered = state.queue_jobs.filter(j => j.status === 'Cancelled');

   if(filtered.length === 0) html += `<tr><td colspan="5" style="padding:40px; color:#999;">No Records.</td></tr>`;

   filtered.forEach(j => {
       html += `
           <tr>
               <td><span class="job-pill" onclick="frappe.set_route('Form', 'Enviro Job Card', '${j.name}')">${j.name}</span></td>
               <td class="client-name">${j.customer || 'N/A'}</td>
               <td>${j.waste_type_label || j.job_card_type || 'N/A'}</td>
               <td>
                   ${j.status !== 'Cancelled' ? `<button class="btn-schedule" onclick="window.ph2_modal('${j.name}')">Schedule</button>` : `<span style="color:#ef4444;font-weight:bold;">DELETED</span>`}
               </td>
               <td>
                   ${j.status !== 'Cancelled' ? `
