                   </button>
                   ` : ''}
               </td>
           </tr>
       `;
   });

   html += `</tbody></table></div></div>`;


   // RIGHT PANEL (Matrix Grid)
   html += `<div class="sched-right">
      <div class="matrix-container">
         <table class="matrix-table">
            <thead>
               <tr>
                  <th class="time-header">Timeline</th>
   `;

   if (state.grid_mode === 'vehicles') {
       state.vehicles.forEach(v => {
          html += `<th>${v.license_plate || v.name}</th>`;
       });
   } else if (state.grid_mode === 'members') {
       state.employees.filter(e => e.status === 'Active').forEach(emp => {
          let img = emp.image || '/assets/frappe/images/default-avatar.png';
          html += `<th>
            <div class="member-header">
