            </div>
          </th>`;
       });
   } else if (state.grid_mode === 'terminated') {
       state.employees.filter(e => e.status !== 'Active').forEach(emp => {
          let img = emp.image || '/assets/frappe/images/default-avatar.png';
          html += `<th>
