   state.dates.forEach(d => {
       let dStr = moment(d).format('YYYY-MM-DD');
       html += `<tr>
           <td class="time-cell">
              <div class="time-day">${d.toLocaleDateString("en-AU", { weekday: 'long'})}</div>
              <div class="time-date">${frappe.datetime.str_to_user(dStr)}</div>
           </td>
       `;

       if (state.grid_mode === 'vehicles') {
           state.vehicles.forEach(v => {
               let vJobs = state.scheduled_jobs.filter(j => j.scheduled_start_date === dStr && j.vehicle === v.name && j.status !== 'Cancelled');
               html += `<td>`;
               vJobs.forEach(vj => {
                   let displayStatus = vj.status || 'Allocated';
                   let statusClass = (displayStatus === 'Completed') ? 'completed' : '';
                   html += `<div class="sched-event ${statusClass}" onclick="frappe.set_route('Form', 'Enviro Job', '${vj.name}')">
                       <div class="ev-title">${vj.name}</div>
                       <div class="ev-driver">${vj.driver || 'Driver Pending'}</div>
                       <div class="ev-status ${statusClass}">${displayStatus}</div>
                   </div>`;
               });
               html += `</td>`;
           });
       } else {
           let emps_to_show = state.grid_mode === 'members' ? state.employees.filter(e => e.status === 'Active') : state.employees.filter(e => e.status !== 'Active');
           emps_to_show.forEach(emp => {
               let empJobs = state.scheduled_jobs.filter(j => {
                   if (j.scheduled_start_date !== dStr || j.status === 'Cancelled') return false;
                   return j.driver === emp.name || (j.team_members && j.team_members.includes(emp.name));
               });
               html += `<td>`;
               empJobs.forEach(vj => {
                   let displayStatus = vj.status || 'Allocated';
                   let statusClass = (displayStatus === 'Completed') ? 'completed' : '';
                   html += `<div class="sched-event ${statusClass}" onclick="frappe.set_route('Form', 'Enviro Job', '${vj.name}')">
                       <div class="ev-title">${vj.name}</div>
                       <div class="ev-driver">${vj.vehicle || 'Vehicle Pending'}</div>
                       <div class="ev-status ${statusClass}">${displayStatus}</div>
                   </div>`;
               });
               html += `</td>`;
           });
       }
       html += `</tr>`;
   });

   html += `        </tbody>
         </table>
      </div>
   </div></div>`;
   root_element.innerHTML = html;
   attach_listeners();
}

function attach_listeners() {
    // Mode Toggles
    root_element.querySelectorAll('.toggle-btn').forEach(btn => {
        btn.addEventListener('click', function() {
            state.grid_mode = this.getAttribute('data-mode');
            render();
        });
    });

    // Export Scheduling Report
    const exportBtn = root_element.querySelector('#btn-export-sched');
    if (exportBtn) {
        exportBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            let data_to_export = [];
            if (state.active_tab === 'One-Off' || state.active_tab === 'Reoccurring' || state.active_tab === 'Outsourced') {
                data_to_export = state.queue_jobs.filter(j => j.status !== 'Assigned');
            } else if (state.active_tab === 'Deleted') {
                data_to_export = state.queue_jobs.filter(j => j.status === 'Cancelled');
            }
            if (data_to_export.length === 0) {
                frappe.show_alert({message: 'No data to export', indicator: 'orange'});
                return;
            }
            let csvContent = "data:text/csv;charset=utf-8,";
            const headers = ["Job ID", "Customer", "Waste Type", "Status"];
            csvContent += headers.join(",") + "\r\n";
            data_to_export.forEach(j => {
                let row = [j.name, '"' + (j.customer || "").replace(/"/g, '""') + '"', '"' + (j.waste_type_label || j.job_card_type || "").replace(/"/g, '""') + '"', j.status];
                csvContent += row.join(",") + "\r\n";
            });
            const encodedUri = encodeURI(csvContent);
            const link = document.createElement("a");
            link.setAttribute("href", encodedUri);
            link.setAttribute("download", `scheduling_${state.active_tab.toLowerCase()}_report.csv`);
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
        });
    }

    // Date Filters
    const fromInput = root_element.querySelector('#filter-from');
    const toInput = root_element.querySelector('#filter-to');
    const clearBtn = root_element.querySelector('#btn-clear-filters');

    if (fromInput) {
        fromInput.addEventListener('change', (e) => {
            state.from_date = e.target.value;
            fetch_data();
        });
    }
    if (toInput) {
        toInput.addEventListener('change', (e) => {
            state.to_date = e.target.value;
            fetch_data();
        });
    }
    if (clearBtn) {
        clearBtn.addEventListener('click', () => {
            state.from_date = moment().startOf('week').add(1, 'days').format('YYYY-MM-DD');
            state.to_date = moment().startOf('week').add(7, 'days').format('YYYY-MM-DD');
            fetch_data();
        });
    }
}

window.set_tab = function(t) { state.active_tab = t; render(); }
