window.ph2_modal = function(job_id) {
    frappe.model.with_doctype('Enviro Job Card', function() {
        frappe.model.with_doctype('Enviro Job Team Member', function() {
            let d = new frappe.ui.Dialog({
                title: 'Schedule Assignment: ' + job_id,
                fields: [
                    { label: 'Scheduled Start Date', fieldname: 'scheduled_start_date', fieldtype: 'Date', reqd: 1, default: frappe.datetime.get_today() },
                    { label: 'Scheduled Start Time', fieldname: 'scheduled_start_time', fieldtype: 'Time', reqd: 1, default: frappe.datetime.now_time() },
                    { fieldtype: 'Column Break' },
                    { label: 'Scheduled End Date', fieldname: 'scheduled_end_date', fieldtype: 'Date', default: frappe.datetime.get_today() },
                    { label: 'Scheduled End Time', fieldname: 'scheduled_end_time', fieldtype: 'Time' },
                    { fieldtype: 'Section Break', label: 'Resource Allocation' },
                    { label: 'Assign Truck', fieldname: 'vehicle', fieldtype: 'Link', options: 'Vehicle', reqd: 1, get_query: function() { return { query: 'enviro.api.scheduling.get_available_vehicles', filters: { date: d.get_value('scheduled_start_date') } }; } },
                    { label: 'Primary Driver', fieldname: 'driver', fieldtype: 'Link', options: 'Employee', reqd: 1, get_query: function() { return { query: 'enviro.api.scheduling.get_driver_employees', filters: { date: d.get_value('scheduled_start_date') } }; } },
                    { fieldtype: 'Section Break', label: 'Additional Team' },
                    { label: 'Additional Support Team', fieldname: 'team_members', fieldtype: 'Table MultiSelect', options: 'Enviro Job Team Member' }
                ],
                size: 'large',
                primary_action_label: 'Schedule Job',
                primary_action(values) {
                    frappe.call({
                        method: 'enviro.api.scheduling.api_schedule_job',
                        args: { job_id: job_id, payload: JSON.stringify(values) },
                        freeze: true,
                        callback: function(r) {
                            if(!r.exc) {
                                frappe.show_alert({message: "Job Scheduled!", indicator: 'green'});
                                d.hide();
                                fetch_data();
                            }
                        }
                    });
                }
            });

            frappe.call({
                method: "frappe.client.get",
                args: { doctype: "Enviro Job Card", name: job_id },
                callback: function(r) {
                    if(r.message) {
                        let doc = r.message;
                        let team = [];
                        if (doc.team_members && Array.isArray(doc.team_members)) {
                            team = doc.team_members.map(row => row.employee).filter(Boolean);
                        }

                        d.set_values({
                            'scheduled_start_date': doc.scheduled_start_date || frappe.datetime.get_today(),
                            'scheduled_start_time': doc.scheduled_start_time || frappe.datetime.now_time(),
                            'scheduled_end_date': doc.scheduled_end_date || frappe.datetime.get_today(),
                            'scheduled_end_time': doc.scheduled_end_time,
                            'vehicle': doc.vehicle,
                            'driver': doc.driver,
                            'team_members': team
                        });
                    }
                }
            });
            d.show();
        });
    });
}

function fetch_data() {
    frappe.call({
        method: 'enviro.api.scheduling.get_scheduling_data',
        args: {
            from_date: state.from_date,
            to_date: state.to_date,
            include_terminated: 1 // Always fetch all to filter on frontend
        },
        callback: function(r) {
            if(r.message) {
                state.queue_jobs = r.message.queue_jobs || [];
                state.scheduled_jobs = r.message.scheduled_jobs || [];
                state.vehicles = r.message.vehicles || [];
                state.employees = r.message.employees || [];
                render();
            }
        }
    });
}
fetch_data();

