let state = {
    jobs: [],
    from_date: moment().subtract(30, 'days').format('YYYY-MM-DD'),
    to_date: moment().format('YYYY-MM-DD'),
    search_txt: ''
};

function render() {
    if (typeof root_element === 'undefined') return;

    let wrapper = root_element.querySelector('.inv-dash-wrapper');
    if (!wrapper) {
        // Initial render: Build the static structure
        root_element.innerHTML = styles + `
            <div class="inv-dash-wrapper">
                <div class="inv-header">
                    <div class="inv-title">Completed Scheduled Jobs</div>
                </div>

                <div class="inv-table-container">
                    <table class="inv-table">
                        <thead>
                            <tr>
                                <th>Job Code</th>
                                <th>Quote No</th>
                                <th>Completed Date</th>
                                <th>Client Id</th>
                                <th>Client Name</th>
                                <th>Quoted by</th>
                                <th>Quote Amt</th>
                                <th>Details</th>
                                <th>View Quote</th>
                                <th>Current Job Status</th>
                                <th>Status</th>
                                <th>Comments</th>
                            </tr>
                        </thead>
                        <tbody id="inv-tbody">
                            <tr><td colspan="12" style="padding: 40px; color: #94a3b8;">Loading data...</td></tr>
                        </tbody>
                    </table>
                </div>

                <div class="inv-filter-bar">
                    <input type="text" class="search-input" id="inv-search" placeholder="Search Clients" value="${state.search_txt}">
                    <div class="date-group">
                        <span>From :</span>
                        <input type="date" class="date-input" id="inv-from" value="${state.from_date}">
                    </div>
                    <div class="date-group">
                        <span>To :</span>
                        <input type="date" class="date-input" id="inv-to" value="${state.to_date}">
                    </div>
                    <button class="btn-clear" id="inv-clear-btn">Clear</button>
                </div>
            </div>
        `;
        attach_listeners();
    }

    // Surgical Update: Only refresh the table body
    let tbody = root_element.querySelector('#inv-tbody');
    if (tbody) {
        let rowsHtml = '';
        if (state.jobs.length === 0) {
            rowsHtml = `<tr><td colspan="12" style="padding: 40px; color: #94a3b8;">No completed jobs found for this period.</td></tr>`;
        } else {
            state.jobs.forEach(j => {
                let compDate = j.completed_date ? moment(j.completed_date).format('DD-MM-YYYY') : '-';
                rowsHtml += `
                    <tr>
                        <td><span class="pill pill-job" onclick="frappe.set_route('Form', 'Enviro Job', '${j.job_code}')">${j.job_code.split('-').pop()}</span></td>
                        <td style="color: #64748b; font-weight: 600;">${j.quote_no || '-'}</td>
                        <td>${compDate}</td>
                        <td style="background: #f1f5f9; font-weight: 700; width: 60px;">${(j.client_id || "").split('-').pop()}</td>
                        <td style="text-align: left; padding-left: 15px; font-weight: 600;">${j.client_name || 'N/A'}</td>
                        <td>${j.quoted_by || '-'}</td>
                        <td style="background: #f1f5f9; font-weight: 700;">${format_currency(j.quote_amt)}</td>
                        <td><button class="btn-view" onclick="frappe.set_route('Form', 'Enviro Job', '${j.job_code}')">View</button></td>
                        <td>
                            <button class="btn-template" onclick="window.view_template('${j.quote_no}')">View Template</button>
                        </td>
                        <td style="color: #1e293b; font-weight: 600;">${j.job_status}</td>
                        <td><span class="pill pill-completed">Completed</span></td>
                        <td><button class="btn-comments" onclick="window.show_comments('${j.job_code}')">Comments</button></td>
                    </tr>
                `;
            });
        }
        tbody.innerHTML = rowsHtml;
    }
}

function attach_listeners() {
    let search = root_element.querySelector('#inv-search');
    if (search) {
        // Stop bubbling to prevent awesomebar hijacking
        search.addEventListener('keydown', (e) => e.stopPropagation());
        search.addEventListener('keyup', (e) => e.stopPropagation());

        search.addEventListener('input', (e) => {
            state.search_txt = e.target.value;
            fetch_data();
        });
    }

    let from = root_element.querySelector('#inv-from');
    if (from) {
        from.addEventListener('change', (e) => {
            state.from_date = e.target.value;
            fetch_data();
        });
    }

    let to = root_element.querySelector('#inv-to');
    if (to) {
        to.addEventListener('change', (e) => {
            state.to_date = e.target.value;
            fetch_data();
        });
    }

    let clearBtn = root_element.querySelector('#inv-clear-btn');
    if (clearBtn) {
        clearBtn.addEventListener('click', () => {
            state.from_date = '';
            state.to_date = '';
            state.search_txt = '';

            // Manually update input values to match state
            if(search) search.value = '';
            if(from) from.value = '';
            if(to) to.value = '';

            fetch_data();
        });
    }
}

// Global scope functions for template buttons
window.view_template = function(quote_no) {
    if (!quote_no || quote_no === '-') {
        frappe.msgprint("No quotation linked to this job.");
        return;
    }
    frappe.set_route('Form', 'Quotation', quote_no);
}

window.show_comments = function(job_code) {
    frappe.route_options = {"reference_name": job_code};
    frappe.set_route("List", "Communication");
}

function format_currency(val) {
    return new Intl.NumberFormat('en-AU', { style: 'decimal', minimumFractionDigits: 2 }).format(val);
}

function fetch_data() {
    frappe.call({
        method: 'enviro.api.invoice.get_completed_jobs',
        args: {
            from_date: state.from_date,
            to_date: state.to_date,
            search_txt: state.search_txt
        },
        callback: function(r) {
            state.jobs = r.message || [];
            render();
        }
    });
}

// Initial Call
fetch_data();
